for locale in ["es", "en", "fr", "de", "it", "pt-BR"]:
    path = MSG / f"{locale}.json"
    data = json.loads(path.read_text(encoding="utf-8"))
    data["businessTypes"] = BT[locale]
    data["howItWorks"] = HW[locale]
    data["faq"] = FQ[locale]
    data["about"] = AB[locale]
    data["contact"] = CT[locale]
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"✅ Updated {path.name}: +businessTypes +howItWorks +faq +about +contact")

print("\nAll 6 message files updated with Fase 2B translations.")
